"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4825],{14825:e=>{e.exports=JSON.parse('{"slug":"bessent-khe-lifen-peregovory-tramp-si","locale":"es","title":"Bessent y He Lifeng negocian en Nueva York 4 d\xedas antes de la reuni\xf3n de Trump y Xi","description":"El secretario del Tesoro estadounidense, Scott Bessent, se reuni\xf3 el domingo en Nueva York con el viceprimer ministro chino He Lifeng antes de la cita de Trump y Xi del jueves. Est\xe1 en juego la pr\xf3rroga de la tregua comercial; para Rusia, la demanda de petr\xf3leo.","blocks":[{"id":"b001","kind":"paragraph","text":"Bessent escribi\xf3 en X que \xe9l y He Lifeng \xabcontin\xfaan debatiendo las relaciones econ\xf3micas y comerciales\xbb entre Estados Unidos y China antes de la \xabhist\xf3rica reuni\xf3n\xbb de Trump y Xi en Washington, y adjunt\xf3 una foto ante las banderas. No dio m\xe1s detalles. Despu\xe9s calific\xf3 las conversaciones de exitosas y dijo que se centraron en comercio e inteligencia artificial. Xinhua confirm\xf3 el encuentro. La reuni\xf3n presidencial ser\xe1 el jueves 24 de septiembre."},{"id":"b002","kind":"paragraph","text":"La agenda anticipada incluye aranceles, competencia en IA, controles de exportaci\xf3n de semiconductores y posible fabricaci\xf3n de coches el\xe9ctricos chinos en Estados Unidos, con Taiw\xe1n e Ir\xe1n de fondo. Desde la reuni\xf3n de mayo, la relaci\xf3n empeora: funcionarios estadounidenses afirman que China incumple la tregua comercial anual. Pesan las restricciones chinas a minerales cr\xedticos y tierras raras, que ya han provocado interrupciones entre fabricantes estadounidenses y de otros pa\xedses."},{"id":"b003","kind":"paragraph","text":"La tregua tiene un mecanismo sencillo. Hace un a\xf1o acordaron no aumentar los aranceles mutuos ni a\xf1adir restricciones. Es una pausa con fecha de caducidad: dejan de discutir y despu\xe9s deciden si prolongarla. Ese plazo termina y constituye la principal inc\xf3gnita del jueves. No importa tanto que firmen un gran acuerdo como que quiz\xe1 no firmen nada. La tregua acabar\xeda y ambos volver\xedan a tener libertad para imponer aranceles."},{"id":"b004","kind":"paragraph","text":"Las tierras raras sirven de palanca. Son necesarias para electr\xf3nica, bater\xedas y armamento, y China restringe su exportaci\xf3n. Es como una f\xe1brica de coches con un \xfanico proveedor de una pieza: este fija precios y plazos, y sin ella no se monta el veh\xedculo. Por eso una interrupci\xf3n duele m\xe1s que un arancel: el arancel encarece la pieza; sin suministro, la pieza no existe."},{"id":"b005","kind":"paragraph","text":"Los mercados esperan en vez de apostar. Los futuros burs\xe1tiles estadounidenses subieron ligeramente el lunes y el d\xf3lar se mantuvo en un rango estrecho. Nadie quiere adivinar el resultado. No se sabe c\xf3mo terminar\xe1 el jueves, y ambos l\xedderes saben mostrar hasta el \xfaltimo momento tanto disposici\xf3n al acuerdo como a levantarse de la mesa."},{"id":"b006","kind":"paragraph","text":"Para Rusia no hay un canal directo: ning\xfan punto trata sobre sus importaciones ni el rublo. El v\xednculo es largo. Si Estados Unidos y China vuelven a elevar aranceles, se frena el comercio mundial y con \xe9l la demanda petrolera. El petr\xf3leo sostiene ingresos presupuestarios y el tipo de cambio ruso. Si hay acuerdo, desaparece esa presi\xf3n sobre el crudo. No hay una estimaci\xf3n de su magnitud."},{"id":"b007","kind":"paragraph","text":"Para el ciudadano es una noticia que seguir, sin actuar de inmediato. Comprar divisas \xabpor si acaso antes de la cumbre\xbb supone pagar al banco un diferencial por algo que todav\xeda no ha ocurrido. Tampoco es correcto pensar que las guerras comerciales ajenas no afectan a Rusia: mediante el petr\xf3leo llegan al presupuesto y al tipo de cambio, aunque con meses de retraso."}],"sources":[{"label":"https://www.interfax.ru/world/1117310","url":"https://www.interfax.ru/world/1117310"},{"label":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html","url":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html"},{"label":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video","url":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video"},{"label":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20","url":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20"},{"label":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap","url":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap"}],"sourceBodySha256":"c1bc79749a4e70a8e26a07aaaf0de06d665d61f9e8ea4735408da5f270991985"}')}}]);